/* ===== LOGIN (phone + OTP) ===== */
UI.login={step:'phone',phone:'',timer:0};
V.login=()=>{if(S.user&&cur().name==='login'){post.push(()=>go(S.next||'home'));return skel(2)}
 const L=UI.login;
 if(L.step==='phone')return `<div class="stack" style="max-width:420px;margin:10px auto"><div class="center"><div style="font-size:3rem">📱</div><h1>${t('Welcome to ApnaTown')}</h1><p class="t2">${t('Log in or sign up with your mobile number')}</p></div><form data-form="phone" class="stack"><div class="field"><label for="ph">${t('Mobile number')}</label><div class="phone"><span class="cc">+91</span><input class="input" id="ph" name="phone" type="tel" inputmode="numeric" maxlength="10" pattern="[0-9]{10}" required placeholder="98765 43210" autocomplete="tel-national" value="${esc(L.phone)}"></div><span class="hint">${t('We will send a 6-digit OTP by SMS')}</span></div><button class="btn p block">${t('Send OTP')}</button></form><div class="divider"></div><button class="btn g block" data-act="altlogin">✉️ ${t('Continue with email')}</button><button class="btn g block" data-act="altlogin">G ${t('Continue with Google')}</button><a class="btn t" href="#home">${t('Continue as guest')}</a><p class="xs muted center">${t('By continuing you agree to our')} <a href="#terms" style="text-decoration:underline">${t('Terms')}</a> ${t('and')} <a href="#privacy" style="text-decoration:underline">${t('Privacy')}</a>.</p></div>`;
 if(L.step==='otp'){post.push(()=>{const b=$$('.otp input');b[0]&&b[0].focus();clearInterval(UI.otpT);UI.otpT=setInterval(()=>{const el=$('#resend');if(!el)return clearInterval(UI.otpT);const s=Math.max(0,Math.ceil((L.timer-Date.now())/1000));el.innerHTML=s?`${t('Resend OTP in')} ${s}s`:`<button class="btn t sm" data-act="resend">${t('Resend OTP')}</button>`;if(!s)clearInterval(UI.otpT)},500)});
  return `<div class="stack" style="max-width:420px;margin:10px auto"><button class="btn t sm" data-act="otpBack" style="justify-self:start">${ic('cl',16)} ${t('Change number')}</button><div class="center"><h1>${t('Enter OTP')}</h1><p class="t2">${t('Sent to')} +91 ${esc(L.phone)}</p></div>${alertBox('info',`${t('Demo: use OTP')} <b>123456</b>`)}<form data-form="otp" class="stack"><div class="otp" role="group" aria-label="OTP">${[0,1,2,3,4,5].map(i=>`<input inputmode="numeric" maxlength="1" aria-label="${t('Digit')} ${i+1}" data-in="otp" data-i="${i}" autocomplete="${i?'off':'one-time-code'}">`).join('')}</div><div id="otperr" class="errmsg center" role="alert"></div><button class="btn p block">${t('Verify & continue')}</button></form><div class="center small muted" id="resend">${t('Resend OTP in')} 30s</div></div>`}
 return `<div class="stack" style="max-width:420px;margin:10px auto"><div class="center"><div style="font-size:3rem">👋</div><h1>${t('Almost done')}</h1><p class="t2">${t('Tell us your name to complete your profile')}</p></div><form data-form="profile1" class="stack">${field('Your name','name','',{req:1,ac:'name'})}${field('Email (optional)','email','',{type:'email',ac:'email'})}<button class="btn p block">${t('Finish')}</button></form></div>`};
F.phone=d=>{if(!/^\d{10}$/.test(d.phone)){toast(t('Enter a valid 10-digit number'),'alert');return}UI.login={step:'otp',phone:d.phone,timer:Date.now()+30000};render()};
INP.otp=(v,el)=>{el.value=v.replace(/\D/g,'').slice(0,1);const i=+el.dataset.i,b=$$('.otp input');if(el.value&&b[i+1])b[i+1].focus()};
document.addEventListener('keydown',e=>{const el=e.target;if(el.matches&&el.matches('.otp input')&&e.key==='Backspace'&&!el.value){const b=$$('.otp input'),i=+el.dataset.i;if(b[i-1])b[i-1].focus()}});
document.addEventListener('paste',e=>{const el=e.target;if(el.matches&&el.matches('.otp input')){const d=(e.clipboardData.getData('text')||'').replace(/\D/g,'').slice(0,6);if(d.length>1){e.preventDefault();$$('.otp input').forEach((b,i)=>b.value=d[i]||'')}}});
F.otp=()=>{const v=$$('.otp input').map(b=>b.value).join('');if(v!=='123456'){$('#otperr').textContent=t('Wrong OTP. Try 123456 in this demo.');const g=$('.otp');g.animate([{transform:'translateX(-6px)'},{transform:'translateX(6px)'},{transform:'none'}],{duration:220});return}
 const known=D().users.find(u=>u.phone===UI.login.phone);if(known||UI.login.phone==='9876543210'){S.user={id:'u1',name:'Rohit Kumar',phone:UI.login.phone,email:'rohit@example.com'};save();UI.login={step:'phone',phone:'',timer:0};toast(t('Welcome back!'),'check');go(S.next||'home')}else{UI.login.step='profile';render()}};
F.profile1=d=>{S.user={id:'u1',name:d.name,phone:UI.login.phone,email:d.email||''};S.addrs.forEach(a=>{a.name=d.name;a.phone=UI.login.phone});save();UI.login={step:'phone',phone:'',timer:0};toast(t('Profile created. Welcome!'),'check');go(S.next||'home')};
A.otpBack=()=>{UI.login.step='phone';render()};A.resend=()=>{UI.login.timer=Date.now()+30000;toast(t('OTP sent again'),'send');render(true)};A.altlogin=()=>toast(t('Demo: use mobile OTP login'),'info');
/* ===== ACCOUNT ===== */
V.account=()=>{if(!S.user)return `<div class="stack"><h1>${t('Account')}</h1><div class="card pad stack center"><div style="font-size:3rem">👤</div><b>${t('You are browsing as a guest')}</b><p class="small t2">${t('Log in to order, bookmark and review.')}</p><a class="btn p" href="#login" data-act="loginNext">${t('Log in / Sign up')}</a></div>${accountLinks(true)}</div>`;
 return `<div class="stack"><div class="card pad row"><div class="art mini" style="border-radius:50%;--h:20">${esc(S.user.name[0])}</div><div class="grow"><b>${esc(S.user.name)}</b><div class="small t2">+91 ${esc(S.user.phone)}</div></div><a class="btn g sm" href="#profile">${t('Edit')}</a></div>${accountLinks()}<div class="card pad stack"><h3>${t('Switch role')}</h3><p class="small t2">${t('This demo lets you open any dashboard.')}</p><button class="btn o" data-act="demo">${ic('users',18)} ${t('Open demo controls')}</button></div><button class="btn g block" data-act="logout">${ic('logout',18)} ${t('Log out')}</button></div>`};
const accountLinks=guest=>`<div class="card"><div class="stack" style="gap:0">${[...(guest?[]:[['bookmarks','Saved shops & services','bookmark'],['reviews','My reviews','star'],['addresses','Saved addresses','pin'],['profile','Profile & payment methods','user'],['notifications','Notifications','bell'],['prefs','Notification & consent settings','sliders']]),['offers','Offers','tag'],['help','Help & support','info'],['about','About us','store'],['terms','Terms','doc'],['privacy','Privacy policy','lock'],['refund','Refund policy','refresh'],['design','Design system','layers']].map(([r,l,i])=>`<a class="row" href="#${r}" style="padding:14px 16px;border-bottom:1px solid var(--border);min-height:52px">${ic(i,20)}<span class="grow">${t(l)}</span>${ic('cr',16)}</a>`).join('')}</div></div><div class="card pad row between"><span>${ic('globe',18)} ${t('Language')}</span><button class="btn g sm" data-act="lang">${S.lang==='en'?'हिन्दी':'English'}</button></div><div class="card pad row between"><span>${ic('moon',18)} ${t('Theme')}</span><div class="chips">${[['auto','Auto'],['light','Light'],['dark','Dark']].map(([k,l])=>`<button class="chip ${S.theme===k?'on':''}" data-act="theme" data-v="${k}">${t(l)}</button>`).join('')}</div></div>`;
A.logout=()=>confirmBox(t('Log out?'),t('You can log back in anytime with your mobile number.'),t('Log out'),()=>{S.user=null;S.role='customer';save();go('home');toast(t('Logged out'),'logout')});
V.profile=()=>{if(!S.user)return V.login();return `<div class="stack"><h1>${t('Profile')}</h1><form data-form="profile" class="card pad stack">${field('Name','name',S.user.name,{req:1})}${field('Mobile number','phone',S.user.phone,{type:'tel',pattern:'[0-9]{10}'})}${field('Email','email',S.user.email||'',{type:'email'})}<button class="btn p">${t('Save changes')}</button></form>
 <div class="card pad stack"><h3>${t('Payment methods')}</h3><div class="row">${ic('wallet',20)}<span class="grow">UPI · rohit@upi</span><span class="badge sec">${t('Default')}</span></div><button class="btn o sm" data-act="fakeUpload">${ic('plus',16)} ${t('Add payment method')}</button></div>
 <div class="card pad stack"><h3>${t('Privacy')}</h3><button class="btn g" data-act="myData">${ic('doc',18)} ${t('Download my data')}</button><button class="btn d" data-act="delAcct">${ic('trash',18)} ${t('Delete my account')}</button></div></div>`};
F.profile=d=>{S.user={...S.user,...d};save();toast(t('Profile saved'),'check')};
A.myData=()=>sheet(`<h3>${t('Your data')}</h3><p class="small muted">${t('Copy this JSON to keep a backup.')}</p><div class="pre">${esc(JSON.stringify({profile:S.user,addresses:S.addrs,orders:myOrders().map(o=>o.id),bookmarks:S.bookmarks,reviews:D().reviews.filter(r=>r.uid==='u1').length},null,2))}</div><button class="btn p block" data-act="copy" data-v="${esc(JSON.stringify({profile:S.user,addresses:S.addrs}))}">${t('Copy data')}</button>`);
A.delAcct=()=>confirmBox(t('Delete your account?'),t('Your profile, addresses and bookmarks will be erased. Order records are kept for the shop’s accounts.'),t('Delete account'),()=>{S.user=null;S.bookmarks=[];S.addrs=[];S.cart=[];save();go('bye')},true);
V.bye=()=>empty('👋','Your account was deleted','Thank you for using ApnaTown. You can still browse as a guest.','<a class="btn p" href="#home">'+t('Back to home')+'</a>');
V.session=()=>empty('⏱️','Session expired','For your safety you were logged out. Please log in again.','<a class="btn p" href="#login">'+t('Log in')+'</a>');
V.prefs=()=>{const p=S.prefs;return `<div class="stack"><h1>${t('Notification & consent')}</h1><div class="card pad stack"><h3>${t('Channels')}</h3>${toggle('inapp',p.inapp,'In-app notifications','pf')}${toggle('email',p.email,'Email updates','pf')}</div><div class="card pad stack"><h3>WhatsApp</h3>${alertBox('info',t('We will only message you on WhatsApp if you say yes below. You can stop anytime by replying STOP or turning these off.'))}${toggle('wa_orders',p.wa_orders,'Order updates on WhatsApp','pf')}${toggle('wa_offers',p.wa_offers,'Offers & promotions on WhatsApp','pf')}${toggle('wa_enq',p.wa_enq,'Enquiry replies on WhatsApp','pf')}<div class="xs muted">${t('Consent recorded')}: ${fdate(Date.now())} · IP not stored</div></div><button class="btn g" data-act="unsubAll">${t('Unsubscribe from all marketing')}</button><div class="card pad row between"><span>${t('Cookies')}</span><button class="btn g sm" data-act="cookieReset">${t('Change')}</button></div></div>`};
CH.pf=el=>{S.prefs[el.dataset.k]=el.checked;save();toast(t('Preference saved'),'check')};
A.unsubAll=()=>{S.prefs.wa_offers=false;S.prefs.email=false;save();render(true);toast(t('You are unsubscribed from marketing'),'bell')};A.cookieReset=()=>{S.consent.cookies=null;save();render(true)};
const FAQ=[['How do I order?','Pick a shop, add items to the cart and choose home delivery or self-pickup. Pay online or in cash.'],['Why was my order split?','Each shop prepares its own order, so one checkout creates one order per shop with separate IDs.'],['How does delivery OTP work?','You get a 4-digit OTP. Tell it to the rider only when you receive your order.'],['How do refunds work?','Cancel or request a refund from the order page. Admin and the shop are notified and will contact you.'],['I am outside Padrauna','We are live in Padrauna now. Choose “Other cities” in the location picker to join the waitlist.']];
V.help=()=>`<div class="stack"><h1>${t('Help & support')}</h1><div class="stack">${FAQ.map(([q,a])=>`<details class="acc"><summary>${t(q)}${ic('cd',18)}</summary><div>${t(a)}</div></details>`).join('')}</div><div class="card pad stack"><h3>${t('Contact support')}</h3><form data-form="support" class="stack">${field('Your message','m','',{type:'textarea',req:1})}<button class="btn p">${t('Send')}</button></form><div class="row"><a class="btn g grow" href="tel:+919876500000">${ic('phone',16)} ${t('Call')}</a><a class="btn s grow" target="_blank" rel="noopener" href="${waH('9876500000','Hi ApnaTown support')}">${ic('chat',16)} WhatsApp</a></div></div></div>`;
F.support=d=>{notify('admin','Support message',d.m.slice(0,70),'ahome','sys');save();toast(t('Message sent. We will reply soon.'),'send');render(true)};
const legal=(title,paras)=>`<div class="stack" style="max-width:720px"><h1>${t(title)}</h1>${paras.map(p=>`<p class="t2">${t(p)}</p>`).join('')}<div class="xs muted">${t('Sample text for the prototype. Replace with your final legal copy.')}</div></div>`;
V.terms=()=>legal('Terms of use',['ApnaTown connects customers with local shops, service providers and riders in Padrauna.','Shops are responsible for their products, prices and stock. ApnaTown helps resolve disputes.','Reviews must be honest and based on real orders or enquiries. We may remove abusive content.']);
V.privacy=()=>legal('Privacy policy',['We collect your mobile number, addresses and order history to run the service.','Location is optional. We use it only to show nearby shops and calculate delivery.','You can download or delete your data any time from your profile. We message you on WhatsApp only with your consent.']);
V.refund=()=>legal('Refund & cancellation policy',['You can cancel before the shop starts preparing your order. Online payments are refunded to the original method.','For damaged or wrong items, request a refund from the order page within '+D().cfg.refundHrs+' hours of delivery.','Admin and the shop will contact you to resolve every request.']);
V.about=()=>`<div class="stack" style="max-width:720px"><h1>${t('About ApnaTown')}</h1><p class="t2">${t('ApnaTown.in is your town’s own bazaar, online. We help neighbourhood shops, service providers and riders in Padrauna, Kushinagar reach more people, and help you find trusted local businesses fast.')}</p><div class="grid g3">${[['🏪','Local shops'],['🔧','Trusted services'],['🛵','Fast delivery']].map(([e,l])=>`<div class="card pad center"><div style="font-size:2rem">${e}</div><b>${t(l)}</b></div>`).join('')}</div></div>`;
V.nf=()=>empty('🧭','Page not found','The page you are looking for does not exist or has moved.','<a class="btn p" href="#home">'+t('Go home')+'</a>');
V.maintenance=()=>empty('🛠️','We’ll be right back','ApnaTown is under maintenance. Please try again in a few minutes.','<button class="btn p" data-act="retry">'+t('Check again')+'</button>');
V.offline=()=>empty('📡','No internet connection','You can still view saved pages. Reconnect to place orders.','<button class="btn p" data-act="retry">'+t('Try again')+'</button>');
V.err500=()=>errState();
/* generic status setter for owners (vendor/rider/etc) shown on gated screens */
const gateNote=(role)=>{const e=role==='vendor'?biz(S.vend.bid):role==='provider'?svc(S.prov.sid):rider(S.rider.rid);const s=e.status;if(s==='approved')return '';
 const M={pending:['warn','Your application is under review','You can complete your profile now. Selling, orders and payouts unlock after approval.'],rejected:['bad','Your application was rejected','Please fix the issues the admin listed and submit again.'],suspended:['bad','Your account is suspended','You can’t take new orders or edits. Contact support to appeal.'],inactive:['info','Your account is inactive','Reactivate to appear in search again.'],changes:['warn','Changes requested','Update your details and resubmit.']}[s];
 const last=(D().apps.find(a=>a.name===e.name&&a.hist.length)||{hist:[]}).hist.slice(-1)[0];
 return `<div class="stack" style="margin-bottom:12px">${alertBox(M[0],`<b>${t(M[1])}</b> ${apBadge(s)}<br>${t(M[2])}${last?`<br><span class="small">${t('Admin note')}: ${esc(last.note)}</span>`:''}`)}<div class="row wrap-r">${s==='rejected'||s==='changes'?`<button class="btn p sm" data-act="resubmit" data-r="${role}">${t('Re-submit')}</button>`:''}${s==='inactive'?`<button class="btn p sm" data-act="reactivate" data-r="${role}">${t('Reactivate')}</button>`:''}</div></div>`};
A.resubmit=el=>{const r=el.dataset.r,e=r==='vendor'?biz(S.vend.bid):r==='provider'?svc(S.prov.sid):rider(S.rider.rid);e.status='pending';const ap=D().apps.find(a=>a.ref===e.id||a.name===(nm(e.name)||e.name));if(ap){ap.status='pending';ap.ts=Date.now()}notify('admin','Re-submitted: '+nm(e.name),'Awaiting review','aappr','appr');save();render(true);toast(t('Submitted for approval'),'send')};
A.reactivate=el=>{const r=el.dataset.r,e=r==='vendor'?biz(S.vend.bid):r==='provider'?svc(S.prov.sid):rider(S.rider.rid);e.status='approved';save();render(true);toast(t('Reactivated'),'check')};
const canAct=role=>{const e=role==='vendor'?biz(S.vend.bid):role==='provider'?svc(S.prov.sid):rider(S.rider.rid);return e.status==='approved'};
const lockedMsg=role=>`<div class="stack">${gateNote(role)}${empty('🔒','Available after approval','This section unlocks once your account is approved.')}</div>`;
